const invoices=[
  {customer:"Acme Co", amount:1200, days:8},
  {customer:"Globex", amount:3400, days:34},
  {customer:"Initech", amount:900, days:72}
];
return [{ json:{ invoices, count:invoices.length, overdue_total:invoices.reduce((s,i)=>s+i.amount,0) }}];

const d=$input.first().json;
const tone=days=> days>=60?"final notice": days>=30?"firm reminder":"gentle nudge";
const planned=d.invoices.map(i=>({...i, reminder:tone(i.days)}));
return [{ json:{ ...d, planned }}];

const d=$input.first().json;
const worst=d.planned.filter(i=>i.days>=60);
return [{ json:{ ...d, system:"Slack", escalated:worst.length, status:"ok" }}];
